    "body": "Dear All,\n\nIt is our pleasure to invite you to the inaugural session of the National Bioengineering Conference, 11-13th December, organized by the Department of Biotechnology and Medical Engineering.\n\nThe session will be held at TIIR Building Auditorium, FTBI, Thursday, 9:30 am.\n\nAll are cordially invited.\n\nThanks and regards,\nConvenor\n(Dr. Prasoon Kumar, Dr. Amrita Singh, Dr. Anamika Singh and Dr. Mirza Khalid Baig)",
