    "body": "Due to the enforcement of the Essential Commodities Act, 1955 (ECA) to regulate usage of LPG, the HMC is compelled to postpone the Hall Day celebration tentatively for a week. The date of Hall Day celebration will be conveyed to you in due course of time.\n\nThis is issued with the consent of the competent authority.\n\nYour co-operation in this regard is highly solicited.\n\nChief Warden\n\nCopy to: All students through email; All Coordinating Wardens, Wardens & Asst. Wardens of Halls for information & necessary action; Secretary to Director; Registrar.",
