    "body": "Dear all students, faculty and staff,\n\nOur academic year 2026-27 has commenced, and the registration process for the Autumn Semester has been completed for all students, except for a few cases that are pending decision. Classes will commence from tomorrow.\n\nOn this occasion, let us all recall the Vision and Mission of our Institute and work collectively towards their realization.\n\nVision of NIT Rourkela: To become an internationally acclaimed institution of higher learning that will serve as a source of knowledge and expertise for society and be a preferred destination for undergraduate and graduate studies.\n\nMission of NIT Rourkela: To advance and spread knowledge in the area of science and technology, leading to the creation of wealth and the welfare of humanity.\n\nIn case of any difficulty related to academic matters, students are advised to first contact their respective Faculty Advisors, then approach HOD, then Assistant Registrar, then Associate Dean, before writing to the Dean (Academics) if unresolved.\n\nAll emails must be sent from Institute email IDs only.",
