    "preview": "This is to inform you that a nationwide youth outreach programme titled 'Run for Swadeshi' is proposed to...",
    "body": "Dear all,\n\nThis is to inform you that a nationwide youth outreach programme titled 'Run for Swadeshi' is proposed to be organised on 12 January 2026, on the occasion of the 164th Birth Anniversary of Swami Vivekananda.\n\nThe objective of the programme is to sensitise students and youth towards Swadeshi values, the vision of Atmanirbhar Bharat, and the importance of physical fitness, discipline, teamwork, and national unity, inspired by the teachings and ideals of Swami Vivekananda.\n\nIn this regard, SAC is organizing an Expert Lecture on 'Swadeshi values' by eminent speakers on 12.01.2026 at 5:30 pm in BBA. Kindly grace the occasion with your presence to ensure success of the programme.\n\nPresident-SAC",
    "label": "Primary",
    "date": "2026-02-11T19:14:00",
    "read": true,
    "starred": false,
    "important": false
