    "subject": "MSME IDEA HACKATHON 6.0 - Applications Open",
    "preview": "Greetings from FTBI, NIT Rourkela.",
    "body": "Dear All,\n\nGreetings from FTBI, NIT Rourkela.\n\nWe are pleased to inform you that MSME IDEA HACKATHON 6.0 is now open for applications. This is an excellent opportunity for innovators, students, researchers, faculty members, startups, and aspiring entrepreneurs to transform their innovative ideas into impactful ventures with funding support of up to Rs. 15 lakhs.\n\nFTBI, NIT Rourkela is an officially recognized Host Institute/Business Incubator (HI/BI) under the Ministry of MSME.\n\nHow to Apply: Visit my.msme.gov.in/inc, select Odisha as the HI/BI State, then select National Institute of Technology, Rourkela as the Host Institute, and submit your application with the required details.\n\nLast Date to Apply: 14th July 2026.\n\nWith best regards,\nFTBI, NIT Rourkela",
