    "body": "Dear Mr. Aman Gourav Sethi,\n\nGreetings from the Career Development Centre (CDC), National Institute of Technology Rourkela.\n\nWe are pleased to inform you that MECON Limited has completed the preliminary screening of applications received through the campus recruitment process. Based on the eligibility criteria and initial evaluation conducted by the recruitment team, you have been shortlisted to participate in the Online Technical Assessment – Round I.\n\nThe assessment is intended to evaluate candidates on their core engineering fundamentals, quantitative aptitude, logical reasoning, analytical ability, and technical problem-solving skills relevant to the offered role.\n\nThe schedule is as follows:\n\nOrganization: MECON Limited\nProcess: Online Technical Assessment – Round I\nMode: Online (Computer-Based Assessment)\nVenue: CDC Computer Laboratory, TIIRE Building, National Institute of Technology Rourkela\n\nAssessment Schedule\n\nDate: 14 April 2026 (Tuesday)\nReporting Time: 06:30 PM\nAssessment Time: 07:00 PM\n\nCandidate Particulars\n\nCandidate Name: Aman Gourav Sethi\nCollege Roll Number: 719MM1041\nStudent ID: 54201\n\nCandidates are requested to carefully note the following instructions:\n\nCandidates should report to the venue at least thirty minutes before the scheduled commencement of the assessment. \n\nOriginal Institute Identity Card must be produced during attendance verification. \n\nFormal dress code is mandatory throughout the assessment. \n\nThe assessment shall be conducted through the designated computer systems provided by the institute. Candidates are advised to immediately report any technical issues before the commencement of the examination. \n\nMobile phones, smart watches, calculators, storage devices, and all electronic gadgets are strictly prohibited inside the assessment hall unless specifically authorized. \n\nAny unfair practice, impersonation, or violation of examination guidelines shall result in immediate disqualification from the recruitment process. \n\nCandidates must strictly comply with the instructions issued by the invigilators and CDC officials. \n\nCandidates are advised to remain seated until the assessment has concluded and official instructions have been announced. \n\nPlease note that this communication has been issued solely for the purpose of informing you about the Online Technical Assessment – Round I. It should not be interpreted as an offer of employment or confirmation of selection. The final recruitment decision shall remain solely with MECON Limited.\n\nWe wish you success in the forthcoming assessment.\n\nRegards,\n\nCareer Development Centre (CDC)\nNational Institute of Technology Rourkela\n\nEmail 2 – Online Technical Assessment – Round II\n\nSubject: Invitation for Online Technical Assessment – Round II | MECON Limited Campus Recruitment Process",
