    "body": "Dear Mr. Aman Gourav Sethi,\n\nGreetings from the Career Development Centre (CDC), National Institute of Technology Rourkela.\n\nWe are pleased to inform you that, after evaluating your performance in the previous stages of the campus recruitment process, MOIL Limited (Manganese Ore (India) Limited) has shortlisted your candidature for Group Discussion – Round II.\n\nThis stage has been designed to further assess your communication skills, leadership potential, analytical thinking, teamwork, interpersonal effectiveness, confidence, and ability to contribute meaningfully in a professional group environment.\n\nThe details are as follows:\n\nOrganization: MOIL Limited (Manganese Ore (India) Limited)\nProcess: Group Discussion – Round II\nVenue: CDC, TIIRE Building, National Institute of Technology Rourkela\n\nGroup Discussion Schedule\n\nDate: 08 July 2026 (Wednesday)\nReporting Time: 06:30 PM\nGroup Discussion Commencement: 07:00 PM\n\nCandidate Details\n\nCandidate Name: Aman Gourav Sethi\nCollege Roll Number: 719MM1041\nStudent ID: 54201\n\nCandidates are requested to carefully observe the following instructions:\n\nCandidates should report to the venue before the scheduled reporting time for attendance and seating arrangements. \n\nCarry your original Institute Identity Card for identity verification. \n\nCandidates are expected to appear in formal business attire throughout the recruitment process. \n\nCarry at least two copies of your latest resume for reference during the discussion. \n\nMobile phones, smart watches, Bluetooth devices, and all electronic gadgets must remain switched off throughout the Group Discussion. \n\nCandidates should actively participate while maintaining professionalism, courtesy, discipline, and respect towards fellow participants. \n\nAny act of misconduct, indiscipline, or violation of placement guidelines may result in immediate disqualification from the recruitment process. \n\nCandidates are advised to remain available until the completion of the discussion and until further instructions are communicated by the recruitment coordinators. \n\nPlease note that this communication has been issued solely to notify you regarding Group Discussion – Round II. Participation in this assessment shall not be construed as an offer of employment, appointment, or confirmation of final selection. The final recruitment decision shall remain exclusively with MOIL Limited (Manganese Ore (India) Limited).\n\nWe congratulate you on successfully progressing to this stage of the recruitment process and extend our best wishes for the upcoming Group Discussion.\n\nRegards,\n\nCareer Development Centre (CDC)\nNational Institute of Technology Rourkela",
    "label": "Primary",
    "date": "2026-07-03T17:03:00",
    "read": true,
    "starred": false,
    "important": true
