    "body": "Dear Mr. Aman Sethi,\n\nGreetings from Rashtriya Ispat Nigam Limited.\n\nWe are pleased to inform you that, based on your performance in the campus recruitment process conducted at National Institute of Technology, Rourkela, you have been professionally shortlisted and selected for the position of Junior Executive – Field Engineer, subject to successful completion of the remaining recruitment formalities and verification process.\n\nIn continuation of the selection process, you are requested to submit the following documents for verification and processing purposes:\n\nRecent Passport Size Photograph\nGovernment-issued Photo Identification Proof\nInstitute Identity Card\nProof of Date of Birth\nCollege Roll Number: 719MM1041\nStudent ID: 54201\n\nCandidates are advised to ensure that all submitted documents are clear, valid, and self-attested wherever applicable. Any discrepancy identified during the verification process may result in the cancellation of candidature.\n\nThe documents may be submitted electronically in PDF format through the designated placement coordination channel within the prescribed timeline communicated separately.\n\nPlease note that timely submission of all required documents is mandatory for completion of the subsequent stages of the recruitment process.\n\nWe appreciate your continued participation and cooperation throughout the selection procedure and congratulate you on being selected for the position of Junior Executive – Field Engineer. We wish you success in the forthcoming stages.\n\nRegards,\nRecruitment & Selection Division\nRashtriya Ispat Nigam Limited\n\nNote:\nThis communication is intended solely for the purpose of document submission and further recruitment processing. It does not constitute, imply, or guarantee a final offer of employment, appointment, or engagement with Rashtriya Ispat Nigam Limited. Final selection shall remain subject to successful completion of all stages of evaluation, document verification, medical fitness requirements, and approval by the competent authority.",
