    "subject": "Dussehra Greetings from the Bureau of Indian Standards (BIS)",
    "preview": "Greetings from the Bureau of Indian Standards (BIS)! On the auspicious occasion of Dussehra, we exte...",
    "body": "Dear Mr. Aman Gourav Sethi,\n\nGreetings from the Bureau of Indian Standards (BIS)!\n\nOn the auspicious occasion of Dussehra, we extend our warmest wishes to you and your family.\n\nMay this joyous festival, symbolising the victory of good over evil, truth over falsehood, and righteousness over adversity, bring happiness, prosperity, good health, and success into your lives.\n\nWe hope that the spirit of Dussehra inspires you to continue striving for excellence, integrity, and dedication in all your personal and professional endeavours.\n\nMay the coming year bring new opportunities, peace, and countless reasons to celebrate with your loved ones.\n\nWishing you and your entire family a very Happy and Prosperous Dussehra!\n\nWarm regards,\nThe BIS Team\nBureau of Indian Standards (BIS)\nGovernment of India",
