    "subject": "Happy Dussehra – Warm Wishes from Rashtriya Ispat Nigam Limited (RINL)",
    "preview": "Warm greetings from Rashtriya Ispat Nigam Limited (RINL)! On the auspicious occasion of Dussehra, we...",
    "body": "Dear Mr. Aman Gourav Sethi,\n\nWarm greetings from Rashtriya Ispat Nigam Limited (RINL)!\n\nOn the auspicious occasion of Dussehra, we extend our heartfelt wishes to you and your family.\n\nMay the triumph of good over evil inspire you to embrace new opportunities with confidence, determination, and optimism. May this festive season bring your family abundant happiness, good health, harmony, and prosperity.\n\nAs we celebrate this occasion of courage, righteousness, and new beginnings, we hope that you continue to achieve success in your academic and professional pursuits.\n\nWe value your association with the ongoing recruitment process and wish you and your loved ones a joyful, peaceful, and prosperous festive season.\n\nWishing you and your family a very Happy Dussehra!\n\nMay the divine blessings of this auspicious festival illuminate your home with happiness and success.\n\nWarm regards,\n\nRecruitment & Selection Team\nRashtriya Ispat Nigam Limited (RINL)\nVisakhapatnam Steel Plant\nVisakhapatnam, Andhra Pradesh",
